// workspaceNestedParentFieldOptions projects the caller's selection onto the
// parent write: relationship members are dropped, because loading them there
// would run before the nested rows exist and return a stale set, and the primary
// key is forced on because every nested write keys on it. A nil
// selection passes through — the parent reads that as "every column".
func workspaceNestedParentFieldOptions(fo *WorkspaceFieldOptions) *WorkspaceFieldOptions {
	if fo == nil {
		return nil
	}
	scalars := *fo
	scalars.Activities = nil
	scalars.APITokens = nil
	scalars.Attachments = nil
	scalars.Comments = nil
	scalars.Cycles = nil
	scalars.Invitations = nil
	scalars.Labels = nil
	scalars.Projects = nil
	scalars.SsoConnections = nil
	scalars.Tasks = nil
	scalars.Teams = nil
	scalars.TimeEntries = nil
	scalars.Users = nil
	scalars.ID = true
	return &scalars
}

// workspaceNestedSelectsRelationship reports whether the caller selected any
// relationship, which is the only thing that earns the terminal re-read. A nil
// FieldOptions selects none, so the parent comes back with its relationship
// members unpopulated — on the edges the call just wrote as well as every other.
func workspaceNestedSelectsRelationship(fo *WorkspaceFieldOptions) bool {
	if fo == nil {
		return false
	}
	return fo.Activities != nil || fo.APITokens != nil || fo.Attachments != nil || fo.Comments != nil || fo.Cycles != nil || fo.Invitations != nil || fo.Labels != nil || fo.Projects != nil || fo.SsoConnections != nil || fo.Tasks != nil || fo.Teams != nil || fo.TimeEntries != nil || fo.Users != nil
}

// nestedResolvedTenantCtx resolves the tenant once for a whole nested write,
// before the transaction opens, so every inner call inherits it off ctx instead
// of re-invoking the user resolver: the tenant resolves at most once per
// mutation, nested children included. The inner writes route through other
// entity clients, and the stash each of them makes is scoped to its own
// hook-handler ctx — it never escapes back here, so without this hoist a
// two-edge nested write resolved three to ten times.
//
// Only the raw resolver value is cached. No tenancy.required branch is taken
// here, which is what lets a *shared* parent hoist for a tenanted child: each
// inner call still applies its own table's required setting to the value.
// Hoisting a decision instead would hand this table's reading of a zero
// resolver to children configured fail-closed.
//
// The other two resolution modes need no hoist and get none: SkipTenancy
// resolves nothing anywhere, and an explicit tenant already reaches every inner
// call through nestedChildOptions and short-circuits ahead of the cache.
func (c *workspaceClient) nestedResolvedTenantCtx(ctx context.Context, options CallOptions[WorkspaceFieldOptions]) (context.Context, error) {
	if options.SkipTenancy || options.Tenant != nil {
		return ctx, nil
	}
	resolvedTenant, err := c.tenantValue(ctx)
	if err != nil {
		return nil, err
	}
	return tenancy.WithResolvedTenant(ctx, resolvedTenant), nil
}

// UpdateWithRelated updates a workspace together with rows on its nested
// relationships, in a single transaction.
//
// It is CreateWithRelated with the parent write swapped and the nested blocks
// widened: `disconnect` and `clear` become expressible, because the parent
// already exists and there are rows to unlink. Everything else — the
// transaction, the per-edge executors, the error attribution and the terminal
// re-read — is shared, so the two cannot drift.
func (c *workspaceClient) UpdateWithRelated(ctx context.Context, id uuid.UUID, input *UpdateWorkspaceWithRelatedInput, opts ...func(*CallOptions[WorkspaceFieldOptions])) (*Workspace, error) {
	if input == nil {
		return nil, fmt.Errorf("update workspace with related: %w", ErrNilInput)
	}
	options := resolveCallOptions(opts)

	ctx, err := c.nestedResolvedTenantCtx(ctx, options)
	if err != nil {
		return nil, fmt.Errorf("update workspace with related: resolve tenant: %w", err)
	}

	var result *Workspace
	err = database.WithTransaction(ctx, c.querier, "update_workspace_with_related", func(ctx context.Context) error {
		// Parent first, and its own tenant check is what authorizes every
		// nested write below. An input with no field set issues no UPDATE and
		// returns the row unchanged, which is what makes a
		// nested-only call cost nothing on the parent.
		parent, err := c.Update(ctx, id, &input.Workspace, func(o *CallOptions[WorkspaceFieldOptions]) {
			*o = options
			o.FieldOptions = workspaceNestedParentFieldOptions(options.FieldOptions)
			o.LockMode = sql.LockNone
		})
		if err != nil {
			return err
		}
		result = parent

		if err := c.applyWorkspaceAPITokensNested(ctx, parent, input.APITokens, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceActivitiesNested(ctx, parent, input.Activities, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceAttachmentsNested(ctx, parent, input.Attachments, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceCommentsNested(ctx, parent, input.Comments, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceCyclesNested(ctx, parent, input.Cycles, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceInvitationsNested(ctx, parent, input.Invitations, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceLabelsNested(ctx, parent, input.Labels, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceProjectsNested(ctx, parent, input.Projects, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceSsoConnectionsNested(ctx, parent, input.SsoConnections, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceTasksNested(ctx, parent, input.Tasks, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceTeamsNested(ctx, parent, input.Teams, options); err != nil {
			return err
		}

		if err := c.applyWorkspaceTimeEntriesNested(ctx, parent, input.TimeEntries, options); err != nil {
			return err
		}

		if workspaceNestedSelectsRelationship(options.FieldOptions) {
			reloaded, err := c.Get(ctx, parent.ID, func(o *CallOptions[WorkspaceFieldOptions]) {
				*o = options
				o.SkipHooks = true
				o.LockMode = sql.LockNone
			})
			if err != nil {
				return err
			}
			result = reloaded
		}
		return nil
	}, database.TxOptions{CallbackMode: c.callbackMode})
	if err != nil {
		return nil, fmt.Errorf("update workspace with related: %w", err)
	}
	return result, nil
}

// applyWorkspaceAPITokensNested applies the Workspace.APITokens block.
//
// One executor per edge, shared by every `…WithRelated` family: the per-edge
// verb set is a property of this one function rather than a condition repeated
// in three templates, so the families cannot drift.
//
