// Exists returns true if a workspace with the given primary key exists.
func (c *workspaceClient) Exists(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[WorkspaceFieldOptions])) (bool, error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpExists, Table: TableWorkspaces, Schema: "public",
		PK: id, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)
		conds := []sql.Condition{sql.Where(c.dialect.QuoteIdentifier("id")).Eq(id)}

		query, args := sql.BuildExists(c.dialect, c.table, conds)

		var exists bool
		if err := conn.QueryRow(ctx, query, args...).Scan(&exists); err != nil {
			return false, fmt.Errorf("exists workspace: %w", err)
		}
		return exists, nil
	})
	if err != nil {
		return false, err
	}
	return result.(bool), nil
}

// ExistsWhere returns true if any workspace matches the given filter.
func (c *workspaceClient) ExistsWhere(ctx context.Context, filter *WorkspaceFilter, opts ...func(*CallOptions[WorkspaceFieldOptions])) (bool, error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpExists, Table: TableWorkspaces, Schema: "public",
		Input: filter, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)

		// A relationship filter compiles to a correlated EXISTS carrying the
		// *target's* tenant predicate, so the tenant is
		// resolved before the conditions are built rather than appended after them.
		filterOpts, filterErr := c.filterOptions(ctx, filter, options.SkipTenancy, options.Tenant)
		if filterErr != nil {
			return nil, fmt.Errorf("exists workspaces: %w", filterErr)
		}

		var conds []sql.Condition
		if filter != nil {
			conds = filter.ToConditions(c.dialect, filterOpts...)
		}

		query, args := sql.BuildExists(c.dialect, c.table, conds)

		var exists bool
		if err := conn.QueryRow(ctx, query, args...).Scan(&exists); err != nil {
			return false, fmt.Errorf("exists workspace where: %w", err)
		}
		return exists, nil
	})
	if err != nil {
		return false, err
	}
	return result.(bool), nil
}

// Count returns the number of workspaces matching the given filter.
// A nil filter counts all workspaces.
func (c *workspaceClient) Count(ctx context.Context, filter *WorkspaceFilter, opts ...func(*CallOptions[WorkspaceFieldOptions])) (int64, error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpCount, Table: TableWorkspaces, Schema: "public",
		Input: filter, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)

		// A relationship filter compiles to a correlated EXISTS carrying the
		// *target's* tenant predicate, so the tenant is
		// resolved before the conditions are built rather than appended after them.
		filterOpts, filterErr := c.filterOptions(ctx, filter, options.SkipTenancy, options.Tenant)
		if filterErr != nil {
			return nil, fmt.Errorf("count workspaces: %w", filterErr)
		}

		var conds []sql.Condition
		if filter != nil {
			conds = filter.ToConditions(c.dialect, filterOpts...)
		}

		query, args := sql.BuildCount(c.dialect, c.table, conds)

		var count int64
		if err := conn.QueryRow(ctx, query, args...).Scan(&count); err != nil {
			return int64(0), fmt.Errorf("count workspaces: %w", err)
		}
		return count, nil
	})
	if err != nil {
		return 0, err
	}
	return result.(int64), nil
}

// Paginate returns a page of workspaces with total count for offset-based pagination.
// A nil filter paginates all workspaces.
func (c *workspaceClient) Paginate(ctx context.Context, input PaginateInput[WorkspaceFilter], opts ...func(*CallOptions[WorkspaceFieldOptions])) (*PaginateResult[Workspace], error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableWorkspaces, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[WorkspaceFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate workspaces count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		workspaces, err := c.GetMany(ctx, &GetWorkspacesInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate workspaces: %w", err)
		}

		return &PaginateResult[Workspace]{
			Items:      workspaces,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[Workspace]), nil
}

// Connection returns a Relay-style cursor-paginated connection of workspaces.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *workspaceClient) Connection(ctx context.Context, input ConnectionInput[WorkspaceFilter], opts ...func(*CallOptions[WorkspaceFieldOptions])) (*Connection[Workspace], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection workspaces: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableWorkspaces, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[WorkspaceFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection workspaces count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeCursor(*input.After)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeCursor(*input.Before)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		workspaces, err := c.GetMany(ctx, &GetWorkspacesInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection workspaces: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(workspaces) > limit
		if hasMore {
			workspaces = workspaces[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(workspaces)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[Workspace], len(workspaces))
		for i, row := range workspaces {
			cursor, err := encodeWorkspaceCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[Workspace]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[Workspace]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[Workspace]), nil
}

// encodeWorkspaceCursor encodes cursor key values as a base64 JSON string.
func encodeWorkspaceCursor(keys []string, w *Workspace) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			out["id"] = w.ID
		case "name":
			out["name"] = w.Name
		case "slug":
			out["slug"] = w.Slug
		case "created_at":
			out["created_at"] = w.CreatedAt
		case "updated_at":
			out["updated_at"] = w.UpdatedAt
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode workspace cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// StreamWorkspacesInput holds query parameters for streaming workspaces records.
